-- his root (place, yaw) / wrist (place, angles) at a frame of his half, in the world for an entity at (pos, ang); nil: no such half
local function at(t, w, f)
	local n = #t / w
	f = math.Clamp(f, 0, n - 1)
	local i = math.min(math.floor(f), n - 2)
	return i * w, f - i
end
function ALEX_MERCER_GRABROOT(ent, anim, frame)
	local P = ALEX_MERCER_GRABPAIR[anim]
	if not P then return end
	local t = P.root
	local a, k = at(t, 4, frame)
	return LocalToWorld(Vector(Lerp(k, t[a + 1], t[a + 5]), Lerp(k, t[a + 2], t[a + 6]), Lerp(k, t[a + 3], t[a + 7])), Angle(0, Lerp(k, t[a + 4], t[a + 8]), 0),
		ent:GetPos(), ent:GetAngles())
end
function ALEX_MERCER_GRABWRIST(ent, anim, frame)
	local P = ALEX_MERCER_GRABPAIR[anim]
	if not P then return end
	local t = P.wrist
	if not t then return end
	local a, k = at(t, 6, frame)
	return LocalToWorld(Vector(Lerp(k, t[a + 1], t[a + 7]), Lerp(k, t[a + 2], t[a + 8]), Lerp(k, t[a + 3], t[a + 9])),
		Angle(Lerp(k, t[a + 4], t[a + 10]), Lerp(k, t[a + 5], t[a + 11]), Lerp(k, t[a + 6], t[a + 12])), ent:GetPos(), ent:GetAngles())
end
